def next_Perfect_Square(N):
    """
    Return the smallest perfect square that is strictly greater than the integer N.
    """
    if N < 0:
        # For negative numbers the first perfect square greater than N is 0
        if N < 0:
            return 0
    # Find the integer square root of N
    root = int(N**0.5)
    # If root**2 is not greater than N, increment root until it is
    if root * root <= N:
        root += 1
    return root * root

