def babylonian_squareroot(number, tolerance=1e-12, max_iter=1000):
    """
    Compute the square root of a non‑negative number using the Babylonian (Newton’s)
    method. Returns a float approximation that satisfies |x*x - number| < tolerance.
    Raises ValueError for negative inputs.
    """
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number")

    # Handle trivial cases
    if number == 0 or number == 1:
        return float(number)

    # Initial guess: number / 2 or 1, whichever is closer to the actual root
    guess = number / 2.0 if number >= 2 else 1.0

    for _ in range(max_iter):
        new_guess = 0.5 * (guess + number / guess)
        if abs(new_guess * new_guess - number) < tolerance:
            return float(new_guess)
        guess = new_guess

