def count_binary_seq(n):
    """Return the number of binary sequences of length 2n with equal sums in the
    first and last halves. This equals the binomial coefficient C(2n, n)."""
    if n < 0:
        raise ValueError("n must be non‑negative")
    return math.comb(2 * n, n)

