import re
from typing import Union, Optional

def _parse_value(x: Union[int, float, str]) -> Optional[float]:
    """
    Convert a numeric input to a float.
    Strings with ',' as decimal separator are supported.
    Returns None if conversion fails.
    """
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        # Replace comma with dot and remove non-digit characters except dot
        normalized = re.sub(r"[^0-9.,-]+", "", x)
        normalized = normalized.replace(",", ".")
        try:
            return float(normalized)
        except ValueError:
            return None
    return None

def compare_one(a: Union[int, float, str], b: Union[int, float, str]) -> Optional[Union[int, float, str]]:
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    val_a = _parse_value(a)
    val_b = _parse_value(b)

    # If parsing failed for any, cannot compare -> treat as unequal and return the type of the larger parsed value if possible
    if val_a is None or val_b is None:
        if val_a is None and val_b is None:
            return None
        if val_a is None:
            return a if isinstance(a, (int, float, str)) else b
        if val_b is None:
            return b if isinstance(b, (int, float, str)) else a

    if val_a == val_b:
        return None
    if val_a > val_b:
        return a
    return b

