def find_star_num(n):
    """Return the n-th star number.

    Star numbers are given by the formula:
        S_n = 6*n*(n-1) + 1
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    return 6 * n * (n - 1) + 1

