import re

def is_undulating(n):
    """
    Return True if the decimal representation of the integer n (positive, negative or zero)
    has at least 3 digits and each digit alternates between being greater than and less than
    its neighbors.  The sign of n does not affect the result.
    """
    s = str(abs(int(n)))
    if len(s) < 3:
        return False
    digits = [int(ch) for ch in s]
    # first step: compare first two digits to set direction
    up = digits[1] > digits[0]
    for i in range(1, len(digits) - 1):
        if up:
            if digits[i + 1] <= digits[i]:
                return False
        else:
            if digits[i + 1] >= digits[i]:
                return False
        up = not up
    return True

