def set_left_most_unset_bit(n):
    """
    Return n with the leftmost unset bit set to 1.
    If all bits up to the current highest bit are set, set the next higher bit.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    # Determine current bit length
    bit_len = n.bit_length()
    if bit_len == 0:  # n == 0
        return 1  # set lowest bit

    # Scan bits from the most significant downwards
    for i in range(bit_len - 1, -1, -1):
        if (n >> i) & 1 == 0:
            return n | (1 << i)

    # All bits are set up to bit_len-1, set the next higher bit
    return n | (1 << bit_len)

