def get_max_sum(n):
    memo = {}

    def helper(x):
        if x in memo:
            return memo[x]
        # base case: if x is 0
        if x == 0:
            memo[x] = 0
            return 0
        # compute recursively
        val = helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5)
        if val < x:
            val = x
        memo[x] = val
        return val

    return helper(n)

