def find_lists(Input):
    """
    Count the number of list objects present in the given tuple.
    Nested lists inside other containers are also counted.
    """
    if not isinstance(Input, tuple):
        raise TypeError("Input must be a tuple")
    count = 0
    def _count(item):
        nonlocal count
        if isinstance(item, list):
            count += 1
            for elem in item:
                _count(elem)
        elif isinstance(item, (tuple, set, list)):
            for elem in item:
                _count(elem)
        # other types are ignored
    for element in Input:
        _count(element)
    return count

