def find_lists(Input):
    """
    Counts the number of list objects contained within the given tuple.
    The function recursively counts lists that are nested inside other lists.
    Parameters
    ----------
    Input : tuple
        The tuple to examine for list objects.

    Returns
    -------
    int
        The total number of list objects found inside the tuple.
    """
    if not isinstance(Input, tuple):
        raise TypeError("Input must be a tuple")

    def count_in(item):
        if isinstance(item, list):
            # Count this list and any lists nested within its elements
            return 1 + sum(count_in(sub) for sub in item)
        elif isinstance(item, tuple):
            return sum(count_in(sub) for sub in item)
        else:
            return 0

    return count_in(Input)

