import collections

def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries within `d`.
    A non-nested dictionary has depth 1.
    """
    if not isinstance(d, collections.abc.Mapping):
        return 0
    max_sub_depth = 0
    for v in d.values():
        if isinstance(v, collections.abc.Mapping):
            max_sub_depth = max(max_sub_depth, dict_depth(v))
    return 1 + max_sub_depth

