import math

def is_prime(n: int) -> bool:
    """Return True if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.isqrt(n)) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a: int) -> bool:
    """Return True if the given number is the multiplication of 3 prime numbers, otherwise False.

    The input number a is guaranteed to be less than 100.

    Example:
        is_multiply_prime(30) == True
        30 = 2 * 3 * 5
    """
    if a < 2:
        return False

    # Build list of primes less than a (or up to 100)
    primes = [p for p in range(2, 101) if is_prime(p)]

    # Try all triples of primes (with repetition)
    for i, p1 in enumerate(primes):
        if p1 * p1 * p1 > a:  # optional early break for sorted list
            break
        for p2 in primes[i:]:
            if p1 * p2 * p2 > a:
                break
            for p3 in primes:
                product = p1 * p2 * p3
                if product == a:
                    return True
                if product > a:
                    break
    return False

