def find_lists(Input):
    """
    Count all list objects contained in the input tuple, including nested lists.

    Parameters
    ----------
    Input : tuple
        A tuple that may contain lists or other iterable objects.

    Returns
    -------
    int
        The total number of list instances found within Input.
    """
    def _count(obj):
        if isinstance(obj, list):
            return 1
        # For tuples, sets, lists, etc., iterate over elements
        if isinstance(obj, (tuple, list, set, frozenset)):
            return sum(_count(item) for item in obj)
        return 0

