    """
    Returns the maximum sum that can be obtained for the given integer n using the recurrence:
        f(n) = max( f(n/2) + f(n/3) + f(n/4) + f(n/5), n )
    The division is integer division.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    return _compute(n) if n > 0 else 0

