import math

def count_binary_seq(n: int) -> int:
    """
    Return the number of binary sequences of length 2n such that the sum of the first
    n bits equals the sum of the last n bits.
    This is equal to the central binomial coefficient C(2n, n).
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    return math.comb(2 * n, n)

