    """
    Return True if the numbers in the list are consecutive when sorted.
    Empty list or a single-element list is considered consecutive.
    """
    if len(l) <= 1:
        return True
    sorted_l = sorted(l)
    for i in range(1, len(sorted_l)):
        if sorted_l[i] - sorted_l[i-1] != 1:
            return False
    return True

