import collections

def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries within `d`.
    A dictionary with no nested dictionaries has a depth of 1.
    """
    if not isinstance(d, collections.abc.Mapping):
        raise TypeError("dict_depth expects a dictionary")

    def _depth(obj):
        if isinstance(obj, collections.abc.Mapping) and obj:
            return 1 + max(_depth(v) for v in obj.values())
        elif isinstance(obj, collections.abc.Mapping):
            return 1
        else:
            return 0

    return _depth(d) if d else 0

