def common_element(list1, list2):
    """
    Return True if list1 and list2 share at least one element, False otherwise.
    """
    # Convert the smaller list to a set for efficient lookup
    if len(list1) < len(list2):
        small_set = set(list1)
        for elem in list2:
            if elem in small_set:
                return True
    else:
        small_set = set(list2)
        for elem in list1:
            if elem in small_set:
                return True
