def sequence(n: int) -> int:
    """Return the nth term of the Newman–Conway sequence.

    The sequence is defined by:
        a(1) = 1
        a(2) = 1
        for n > 2:
            if n is even:  a(n) = a(n//2)
            if n is odd:   a(n) = a((n-1)//2) + a((n+1)//2)

    Parameters
    ----------
    n : int
        The 1‑based position in the sequence. Must be a positive integer.

    Returns
    -------
    int
        The nth term of the sequence.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    @lru_cache(maxsize=None)
    def _seq(k: int) -> int:
        if k == 1 or k == 2:
            return 1
        if k % 2 == 0:
            return _seq(k // 2)
        return _seq((k - 1) // 2) + _seq((k + 1) // 2)

    return _seq(n)

