import math

def _sieve(limit: int):
    """Return a list of prime numbers up to `limit` (inclusive)."""
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for num in range(2, int(math.isqrt(limit)) + 1):
        if sieve[num]:
            step = num
            start = num * num
            sieve[start:limit + 1:step] = [False] * len(range(start, limit + 1, step))
    return [i for i, is_prime in enumerate(sieve) if is_prime]

_PRIMES = _sieve(100)

def is_multiply_prime(a: int) -> bool:
    """Return True if `a` is the product of exactly three prime numbers (repetition allowed);
    otherwise return False.

    Assumes a < 100 and a >= 2.
    """
    if a < 2:
        return False

    for i, p1 in enumerate(_PRIMES):
        if p1 > a:
            break
        if a % p1 != 0:
            continue
        a1 = a // p1
        for p2 in _PRIMES[i:]:                    # allow repeats
            if p2 > a1:
                break
            if a1 % p2 != 0:
                continue
            a2 = a1 // p2
            # Now check if a2 is a prime
            if a2 in _PRIMES:
                return True
    return False

