def set_left_most_unset_bit(n: int) -> int:
    """
    Returns ``n`` with the leftmost unset bit set to 1.

    The leftmost unset bit is defined as the most significant bit that is 0
    in the binary representation of ``n``. If ``n`` consists of all 1s
    up to its current bit length, the bit just beyond the current length
    is set (effectively extending the width by one).
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    # Determine current bit length (position of highest 1)
    bit_len = n.bit_length()
    # Scan from the highest bit downwards to find first 0
    for pos in range(bit_len - 1, -1, -1):
        if (n >> pos) & 1 == 0:
            return n | (1 << pos)
    # All bits up to bit_len are 1, so set the next bit
    return n | (1 << bit_len)

