from typing import Dict

def parse_record(line: str) -> Dict[str, object]:
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result: Dict[str, object] = {}
    i = 0
    n = len(line)
    while i < n:
        # Skip leading whitespace
        while i < n and line[i] in " \t":
            i += 1
        if i >= n:
            break

        # Extract a field up to the next unquoted ;
        start = i
        in_quote = False
        escape = False
        field = None
        while i < n:
            ch = line[i]
            if escape:
                escape = False
            elif ch == '\\':
                escape = True
            elif ch == '"':
                in_quote = not in_quote
            elif ch == ';' and not in_quote:
                break
            i += 1
        field = line[start:i].strip()
        # Skip the separator
        if i < n and line[i] == ';':
            i += 1

        if not field:
            continue

        if '=' in field:
            key, value = field.split('=', 1)
            key = key.strip()
            value = value.strip()
            # Handle quoted value
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                # Remove surrounding quotes and handle escaped quotes
                inner = value[1:-1]
                # Replace \" with " and \\ with \
                # We need to treat \\ as literal backslash unless it's before "
                # Simplest: interpret backslash escapes for quote
                res = []
                esc = False
                for c in inner:
                    if esc:
                        res.append(c)
                        esc = False
                    elif c == '\\':
                        esc = True
                    else:
                        res.append(c)
                value = ''.join(res)
            # No trimming for quoted values already done
        else:
            key = field.strip()
            value = True

        result[key] = value

    return result

