    """
    def split_fields(s):
        fields = []
        buff = []
        in_quote = False
        i = 0
        while i < len(s):
            c = s[i]
            if in_quote:
                if c == '\\' and i + 1 < len(s) and s[i+1] == '"':
                    buff.append('"')
                    i += 1
                elif c == '"':
                    in_quote = False
                else:
                    buff.append(c)
            else:
                if c == ';':
                    fields.append(''.join(buff))
                    buff = []
                elif c == '"':
                    in_quote = True
                else:
                    buff.append(c)
            i += 1
        if buff or s.endswith(';'):
            fields.append(''.join(buff))
        return fields

    result = {}
    for raw in split_fields(line):
        if not raw.strip():
            continue
        if '=' in raw:
            key, value = raw.split('=', 1)
            key = key.strip()
            value = value.strip()
            if value.startswith('"') and value.endswith('"'):
                # remove outer quotes and unescape
                inner = value[1:-1]
                inner = inner.replace('\\"', '"')
                result[key] = inner
            else:
                result[key] = value
        else:
            key = raw.strip()
            if key:
                result[key] = True
    return result

# Examples
print(parse_record('name=Ana; city = Lyon'))  # {"name":"Ana","city":"Lyon"}
print(parse_record('note="a;b"; urgent'))     # {"note":"a;b","urgent":True}

import datetime

def count_by_week(dates):
    """dates is a list of "YYYY-MM-DD" strings. Return a dict mapping each ISO week, written
    "YYYY-Www" with the ISO week-numbering year and a two-digit week, to the number of dates in it.

    count_by_week(["2026-06-15", "2026-06-16"]) == {"2026-W25": 2}
    """
    result = {}
    for d_str in dates:
        # Parse date string into a datetime.date object
        year, month, day = map(int, d_str.split('-'))
        dt = datetime.date(year, month, day)
        # Get ISO year and week number
        iso_year, iso_week, _ = dt.isocalendar()
        key = f"{iso_year}-W{iso_week:02d}"
        result[key] = result.get(key, 0) + 1
    return result

# Example usage
if __name__ == "__main__":
    print(count_by_week(["2026-06-15", "2026-06-16"]))  # {"2026-W25": 2}

